<?php
require __DIR__.'/../includes/bootstrap.php';
require_admin();
require __DIR__.'/../includes/upload.php';

$id=(int)($_GET['id']??0);
$error='';
$categoryRows=$pdo?$pdo->query('SELECT id,name,slug,parent_id FROM categories ORDER BY parent_id IS NOT NULL,name')->fetchAll():[];
$parentCategories=array_values(array_filter($categoryRows,static fn($category)=>$category['parent_id']===null));
$childCategories=array_values(array_filter($categoryRows,static fn($category)=>$category['parent_id']!==null));
$parentNamesById=[];foreach($parentCategories as $parent)$parentNamesById[(int)$parent['id']]=$parent['name'];
$article=['title'=>'','slug'=>'','excerpt'=>'','content'=>'','category'=>'','subcategory'=>'','focus_keyword'=>'','meta_title'=>'','meta_description'=>'','canonical_url'=>'','schema_type'=>'Article','faq_json'=>'','featured_image'=>'','status'=>'draft','published_at'=>'','noindex'=>0,'featured'=>0];
if($pdo&&$id){$s=$pdo->prepare('SELECT * FROM articles WHERE id=?');$s->execute([$id]);$article=$s->fetch()?:$article;}

if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    foreach(['title','slug','excerpt','content','category','subcategory','focus_keyword','meta_title','meta_description','canonical_url','schema_type','faq_json','status','published_at'] as $field)$article[$field]=trim($_POST[$field]??'');
    $article['noindex']=isset($_POST['noindex'])?1:0;
    $article['featured']=isset($_POST['featured'])?1:0;
    if($article['title']===''||$article['slug']===''||$article['content']==='')$error='Title, slug and content are required.';
    elseif(!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$article['slug']))$error='Use a lowercase slug with letters, numbers and hyphens only.';
    elseif($article['category']!==''&&!in_array($article['category'],array_column($parentCategories,'name'),true))$error='Select a valid parent category.';
    elseif($article['subcategory']!==''&&$article['category']==='')$error='Select a parent category before choosing a subcategory.';
    elseif($article['subcategory']!==''&&$pdo){$s=$pdo->prepare('SELECT 1 FROM categories child JOIN categories parent ON parent.id=child.parent_id WHERE child.name=? AND parent.name=? LIMIT 1');$s->execute([$article['subcategory'],$article['category']]);if(!$s->fetchColumn())$error='Select a subcategory that belongs to the chosen parent.';}
    elseif(!in_array($article['status'],['draft','scheduled','published','archived'],true))$error='Select a valid status.';
    elseif($article['status']==='scheduled'&&$article['published_at']==='')$error='Publication date and time are required for scheduled articles.';
    elseif($article['canonical_url']!==''&&!filter_var($article['canonical_url'],FILTER_VALIDATE_URL))$error='Canonical URL must be a valid URL.';
    elseif($article['faq_json']!==''&&(!is_array(json_decode($article['faq_json'],true))||json_last_error()!==JSON_ERROR_NONE))$error='FAQ JSON is invalid.';
    try{if(!$error&&!empty($_FILES['featured_image']['name']))$article['featured_image']=save_upload($_FILES['featured_image'],'image');}catch(Throwable $e){$error=$e->getMessage();}
    if(!$error){
        try{
            $publishedAt=$article['published_at']!==''?date('Y-m-d H:i:s',strtotime($article['published_at'])):($article['status']==='published'?date('Y-m-d H:i:s'):null);
            $values=[$article['title'],$article['slug'],$article['excerpt'],$article['content'],$article['category'],$article['subcategory'],$article['focus_keyword'],$article['meta_title'],$article['meta_description'],$article['canonical_url'],$article['schema_type'],$article['faq_json']?:null,$article['featured_image'],$article['status'],$publishedAt,$article['featured'],$article['noindex']];
            if($id){$s=$pdo->prepare('UPDATE articles SET title=?,slug=?,excerpt=?,content=?,category=?,subcategory=?,focus_keyword=?,meta_title=?,meta_description=?,canonical_url=?,schema_type=?,faq_json=?,featured_image=?,status=?,published_at=?,featured=?,noindex=? WHERE id=?');$s->execute([...$values,$id]);log_admin_activity('article_updated','Article ID: '.$id);}
            else{$s=$pdo->prepare('INSERT INTO articles(title,slug,excerpt,content,category,subcategory,focus_keyword,meta_title,meta_description,canonical_url,schema_type,faq_json,featured_image,status,published_at,featured,noindex) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute($values);log_admin_activity('article_created','Article ID: '.$pdo->lastInsertId());}
            header('Location: articles.php');exit;
        }catch(Throwable $e){$error='Unable to save article. Confirm that the database migration has been imported and the slug is unique.';}
    }
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($id?'Edit Article':'New Article')?></title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1><?=e($id?'Edit Article':'New Article')?></h1><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif;?><form method="post" enctype="multipart/form-data" class="card"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><p><label>Title<input name="title" value="<?=e($article['title'])?>" required></label></p><p><label>Slug<input name="slug" value="<?=e($article['slug'])?>" required></label></p><p><label>Parent category<select id="article-category" name="category"><option value="">Select parent category</option><?php foreach($parentCategories as $parent):?><option value="<?=e($parent['name'])?>" <?=$article['category']===$parent['name']?'selected':''?>><?=e($parent['name'])?></option><?php endforeach;?></select></label></p><p><label>Subcategory<select id="article-subcategory" name="subcategory"><option value="">No subcategory</option><?php foreach($childCategories as $child):?><option value="<?=e($child['name'])?>" data-parent="<?=e($parentNamesById[(int)$child['parent_id']]??'')?>" <?=$article['subcategory']===$child['name']?'selected':''?>><?=e(($parentNamesById[(int)$child['parent_id']]??'').' — '.$child['name'])?></option><?php endforeach;?></select></label></p><p><label>Excerpt<textarea name="excerpt"><?=e($article['excerpt']??'')?></textarea></label></p><p><label>Content<textarea name="content" rows="16" required><?=e($article['content']??'')?></textarea></label></p><fieldset><legend>SEO</legend><p><label>Focus keyword<input name="focus_keyword" value="<?=e($article['focus_keyword']??'')?>"></label></p><p><label>Meta title<input name="meta_title" value="<?=e($article['meta_title']??'')?>" maxlength="255"></label></p><p><label>Meta description<textarea name="meta_description"><?=e($article['meta_description']??'')?></textarea></label></p><p><label>Canonical URL<input type="url" name="canonical_url" value="<?=e($article['canonical_url']??'')?>"></label></p><p><label>Schema type<select name="schema_type"><option value="Article">Article</option><option value="BlogPosting" <?=($article['schema_type']??'')==='BlogPosting'?'selected':''?>>BlogPosting</option></select></label></p><label><input type="checkbox" name="noindex" <?=!empty($article['noindex'])?'checked':''?>> Noindex</label></fieldset><p><label>FAQ JSON<textarea name="faq_json" rows="6" placeholder='[{"question":"What is ASMR?","answer":"ASMR is..."}]'><?=e($article['faq_json']??'')?></textarea></label></p><p><label>Status<select name="status"><?php foreach(['draft','scheduled','published','archived'] as $status):?><option value="<?=$status?>" <?=$article['status']===$status?'selected':''?>><?=e(ucfirst($status))?></option><?php endforeach;?></select></label></p><p><label>Publication date and time<input type="datetime-local" name="published_at" value="<?=e(!empty($article['published_at'])?date('Y-m-d\TH:i',strtotime($article['published_at'])):'')?>"></label></p><label><input type="checkbox" name="featured" <?=!empty($article['featured'])?'checked':''?>> Featured article</label><p><label>Featured image<input type="file" name="featured_image" accept="image/jpeg,image/png,image/webp"></label></p><?php if(!empty($article['featured_image'])):?><img src="../<?=e($article['featured_image'])?>" alt="Current featured image" style="max-width:240px;border-radius:10px"><?php endif;?><p><button>Save article</button> <a href="articles.php">Cancel</a></p></form><script>const parentSelect=document.getElementById('article-category'),childSelect=document.getElementById('article-subcategory');function filterChildren(){for(const option of childSelect.options){if(!option.value)continue;const matches=option.dataset.parent===parentSelect.value;option.hidden=!matches;if(!matches&&option.selected)childSelect.value='';}}parentSelect.addEventListener('change',filterChildren);filterChildren();</script></main></body></html>